CREATE TABLE IF NOT EXISTS workspaces(id TEXT PRIMARY KEY,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'ACTIVE',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,display_name TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memberships(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),user_id TEXT NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN ('OWNER','ADMIN','EDITOR','VIEWER')),created_at TEXT NOT NULL,UNIQUE(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS projects(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),name TEXT NOT NULL,description TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS campaigns(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),name TEXT NOT NULL,objective TEXT NOT NULL,audience TEXT NOT NULL,message TEXT NOT NULL,start_date TEXT,end_date TEXT,channels_json TEXT NOT NULL DEFAULT '[]',status TEXT NOT NULL DEFAULT 'PLANNED',planned_budget REAL,actual_spend REAL,actual_spend_status TEXT NOT NULL DEFAULT 'UNKNOWN',approval_state TEXT NOT NULL DEFAULT 'PENDING',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL REFERENCES workspaces(id),title TEXT NOT NULL,description TEXT,area TEXT NOT NULL,priority TEXT NOT NULL DEFAULT 'NORMAL',status TEXT NOT NULL CHECK(status IN ('BACKLOG','TODAY','IN_PROGRESS','WAITING','REVIEW','DONE','CANCELLED')),due_at TEXT,owner_user_id TEXT,linked_record_type TEXT,linked_record_id TEXT,next_action TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
